Lemma pch_scan : forall (k : nat) (i : Z)
    rax ra sp gp tp t0x t1x t2 a3 a4 a5 a6 a7 s5x s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (p : Z) (e1 e2 e3 : word) (g : bool) (j24 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs p
          [CB 24 j24] [C8 e1; C8 e2; C8 e3] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  p0 <= p -> 0 <= i -> p + i < p0 + Z.of_nat (length bs) -> (Z.to_nat (p0 + Z.of_nat (length bs) - (p + i)) <= k)%nat ->
  evt asegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m)
    (MS (pch_ms0 rax sp gp tp t0x t1x t2 (wz 13) (wz p) (wz i) a3 a4 a5 a6 a7
                 s5x (wz (p0 + Z.of_nat (length bs))) (wz (Z.of_nat (length bs))) t3 t4 t5 t6 P IN E)
